sig_hanmi_genentech_deal: {'id': 'sig_hanmi_genentech_deal', 'summary': 'Hanmi Pharm licensed its UCN2 analog HM17321 to Genentech/Roche for $190M upfront and up to $2.3B total, disclosed 2026-08-24; a new non-GLP-1 obesity mechanism just got big-pharma capital behind it.', 'date_of_evidence': '2026-08-24', 'source_count': 1}

sig_ascletis_pipeline: {'id': 'sig_ascletis_pipeline', 'summary': 'Ascletis initiated global Phase III trials for oral small-molecule GLP-1R agonist ASC30 (~4,600 patients, disclosed 2026-08-03) and Phase I trials for amylin agonist ASC36 and its GIPR/GLP-1R combo co-formulation (disclosed 2026-08-10).', 'date_of_evidence': '2026-08-10', 'source_count': 1}

sig_bachem_capacity_commitment: {'id': 'sig_bachem_capacity_commitment', 'summary': 'Bachem confirmed H1 2026 sales up 7.3% in local currency, CHF 148.4M invested in H1 with CHF 350-400M planned for the full year, Building K now live for commercial GMP output, and Sisslerfeld capacity targeted for 2030.', 'date_of_evidence': '2026-07-30', 'source_count': 1}

sig_cdmo_consolidation: {'id': 'sig_cdmo_consolidation', 'summary': 'CordenPharma closed its acquisition of AmbioPharm on 2026-08-03, adding a South Carolina and a Shanghai peptide-manufacturing site to its network; PolyPeptide separately disclosed +42% YoY H1 2026 revenue with improved margin on 2026-08-13.', 'date_of_evidence': '2026-08-13', 'source_count': 2}

sig_capacity_bottleneck_structural: {'id': 'sig_capacity_bottleneck_structural', 'summary': "Peptide-API manufacturing capacity remains a structural constraint on incumbent obesity-drug supply, corroborated across Bachem, PolyPeptide, and both Lilly's and Novo's own investor disclosures.", 'date_of_evidence': '2026-05-15', 'source_count': 4}

sig_scanner_no_pipeline_exposure: {'id': 'sig_scanner_no_pipeline_exposure', 'summary': "The options scanner's entire GLP-1/Peptides theme is five LLY/NVO contracts tagged peak_hype, with asymmetry compressing from 11.5 to 3.78 as strikes move further out of the money and volume falls to single digits; none of the new entrants or CDMOs appear in the scanned universe at all.", 'date_of_evidence': '2026-04-28', 'source_count': 1}
